import { createHmac, randomUUID, timingSafeEqual } from "node:crypto";
import { z } from "zod";
import { SUBSCRIPTION_STATUSES } from "@olnktr/validators";
import {
  JSON_ACK,
  WebhookVerificationError,
  type NormalizedBillingEvent,
  type PaymentProvider,
  type VerifiedWebhook,
} from "./types";

/**
 * Development/test payment provider.
 *
 * It does NOT fake payments: it produces HMAC-signed webhook events that travel
 * through exactly the same verification → inbox → idempotent processing
 * pipeline as real providers. Events are generated by an explicit developer
 * action (the local dev checkout page or tests). Refused in production by
 * environment validation.
 */
export const DEV_SIGNATURE_HEADER = "x-olnktr-dev-signature";
const TOLERANCE_SECONDS = 300;

const devEventSchema = z.object({
  id: z.string().min(8).max(100),
  type: z.string().max(100),
  created: z.number().int(),
  data: z.discriminatedUnion("kind", [
    z.object({
      kind: z.literal("checkout.completed"),
      checkoutSessionId: z.uuid(),
      status: z.enum(SUBSCRIPTION_STATUSES),
      interval: z.enum(["month", "year"]),
      trialDays: z.number().int().min(0).default(0),
      amount: z.number().int().min(0),
      currency: z.string().length(3),
    }),
    z.object({
      kind: z.literal("checkout.failed"),
      checkoutSessionId: z.uuid(),
      amount: z.number().int().min(0),
      currency: z.string().length(3),
      reason: z.string().max(200),
    }),
    z.object({
      kind: z.literal("payment.failed"),
      providerSubscriptionId: z.string().max(100),
      amount: z.number().int().min(0),
      currency: z.string().length(3),
      reason: z.string().max(200),
    }),
    z.object({
      kind: z.literal("payment.succeeded"),
      providerSubscriptionId: z.string().max(100),
      amount: z.number().int().min(0),
      currency: z.string().length(3),
      periodEnd: z.iso.datetime(),
    }),
    z.object({
      kind: z.literal("subscription.deleted"),
      providerSubscriptionId: z.string().max(100),
    }),
  ]),
});
export type DevEvent = z.infer<typeof devEventSchema>;
export type DevEventData = DevEvent["data"];

export function signDevPayload(
  secret: string,
  rawBody: string,
  timestamp = Math.floor(Date.now() / 1000),
): string {
  const signature = createHmac("sha256", secret).update(`${timestamp}.${rawBody}`).digest("hex");
  return `t=${timestamp},v1=${signature}`;
}

/** Builds a signed dev webhook request (used by the dev checkout page and tests). */
export function buildDevWebhook(
  secret: string,
  data: DevEventData,
): { rawBody: string; headers: Headers } {
  const event: DevEvent = {
    id: `dev_evt_${randomUUID()}`,
    type: data.kind,
    created: Math.floor(Date.now() / 1000),
    data,
  };
  const rawBody = JSON.stringify(event);
  return {
    rawBody,
    headers: new Headers({ [DEV_SIGNATURE_HEADER]: signDevPayload(secret, rawBody) }),
  };
}

function verifySignature(
  secret: string,
  rawBody: string,
  header: string | null,
  nowSeconds: number,
): void {
  if (!header) throw new WebhookVerificationError("Missing signature header");
  const parts = Object.fromEntries(
    header.split(",").map((part) => part.split("=", 2) as [string, string]),
  );
  const timestamp = Number(parts.t);
  if (!Number.isInteger(timestamp) || !parts.v1)
    throw new WebhookVerificationError("Malformed signature header");
  if (Math.abs(nowSeconds - timestamp) > TOLERANCE_SECONDS) {
    throw new WebhookVerificationError("Signature timestamp outside tolerance (possible replay)");
  }
  const expected = Buffer.from(
    createHmac("sha256", secret).update(`${timestamp}.${rawBody}`).digest("hex"),
  );
  const received = Buffer.from(parts.v1);
  if (expected.length !== received.length || !timingSafeEqual(expected, received)) {
    throw new WebhookVerificationError("Invalid signature");
  }
}

export function createDevPaymentProvider(options: {
  secret: string;
  appUrl: string;
  now?: () => Date;
}): PaymentProvider {
  const now = options.now ?? (() => new Date());
  return {
    id: "dev",
    currency: "USD",
    capabilities: { managedRenewals: false, planChanges: false },
    webhookAck: JSON_ACK,

    createCheckout(input) {
      const url = new URL("/api/billing/dev/checkout", options.appUrl);
      url.searchParams.set("session", input.checkoutSessionId);
      return Promise.resolve({
        providerSessionId: `dev_cs_${input.checkoutSessionId}`,
        url: url.toString(),
      });
    },

    cancelSubscription: () => Promise.resolve(),

    async verifyWebhook({ rawBody, headers }): Promise<VerifiedWebhook> {
      verifySignature(
        options.secret,
        rawBody,
        headers.get(DEV_SIGNATURE_HEADER),
        Math.floor(now().getTime() / 1000),
      );
      let parsed: DevEvent;
      try {
        parsed = devEventSchema.parse(JSON.parse(rawBody));
      } catch {
        throw new WebhookVerificationError("Malformed event payload");
      }
      const at = new Date(parsed.created * 1000);
      const data = parsed.data;
      let event: NormalizedBillingEvent;
      switch (data.kind) {
        case "checkout.completed": {
          const trialEndsAt =
            data.trialDays > 0 ? new Date(at.getTime() + data.trialDays * 86_400_000) : null;
          const periodEnd = new Date(at);
          if (data.interval === "year") periodEnd.setUTCFullYear(periodEnd.getUTCFullYear() + 1);
          else periodEnd.setUTCMonth(periodEnd.getUTCMonth() + 1);
          event = {
            kind: "checkout.completed",
            checkout: { checkoutSessionId: data.checkoutSessionId },
            providerSubscriptionId: `dev_sub_${data.checkoutSessionId}`,
            providerCustomerId: null,
            status: data.status,
            currentPeriodStart: at.toISOString(),
            currentPeriodEnd: (trialEndsAt ?? periodEnd).toISOString(),
            trialEndsAt: trialEndsAt?.toISOString() ?? null,
            payment:
              data.amount > 0 && !trialEndsAt
                ? {
                    providerPaymentId: `dev_pay_${parsed.id}`,
                    amount: data.amount,
                    currency: data.currency,
                    occurredAt: at.toISOString(),
                  }
                : null,
          };
          break;
        }
        case "checkout.failed":
          event = {
            kind: "checkout.failed",
            checkout: { checkoutSessionId: data.checkoutSessionId },
            payment: {
              providerPaymentId: `dev_pay_${parsed.id}`,
              amount: data.amount,
              currency: data.currency,
              failureCode: "card_declined",
              failureMessage: data.reason,
              occurredAt: at.toISOString(),
            },
          };
          break;
        case "payment.failed":
          event = {
            kind: "payment.failed",
            providerSubscriptionId: data.providerSubscriptionId,
            payment: {
              providerPaymentId: `dev_pay_${parsed.id}`,
              amount: data.amount,
              currency: data.currency,
              failureCode: "card_declined",
              failureMessage: data.reason,
              occurredAt: at.toISOString(),
            },
          };
          break;
        case "payment.succeeded":
          event = {
            kind: "payment.succeeded",
            providerSubscriptionId: data.providerSubscriptionId,
            payment: {
              providerPaymentId: `dev_pay_${parsed.id}`,
              amount: data.amount,
              currency: data.currency,
              occurredAt: at.toISOString(),
            },
            periodEnd: data.periodEnd,
          };
          break;
        case "subscription.deleted":
          event = {
            kind: "subscription.deleted",
            providerSubscriptionId: data.providerSubscriptionId,
            endedAt: at.toISOString(),
          };
          break;
      }
      return { providerEventId: parsed.id, type: parsed.type, events: [event] };
    },
  };
}
